    // from whatever the level is now (setLevel may have moved it).
    var gained = Math.floor((lines + cleared) / LINES_PER_LEVEL) - Math.floor(lines / LINES_PER_LEVEL);
    lines += cleared;
    if (gained > 0) {
      level += gained;
      if (timer !== null) startTimer();
    }
  }

