  // comes in; a full slot swaps with it. One hold per piece until it locks.
  function holdPiece() {
    if (status !== "running" || !current || !canHold) return;
    var type = current.type;
    current = null;
    canHold = false;
    if (hold === null) {
      hold = type;
      spawn();
    } else {
