  function gravityInterval() {
    return Math.max(100, 1000 - (level - 1) * 100);
  }

  function onTimer() {
    gravityStep();
    render();
  }

  function startTimer() {
    stopTimer();
    timer = setInterval(onTimer, gravityInterval());
  }

  function stopTimer() {
    holdBoxEl.classList.toggle("hold-used", !canHold);

    overlayEl.hidden = status !== "gameover";
  }

  // ---- Game control ----
  function newGame(q) {
    board = emptyBoard();
    bag = [];
    queue = sanitizeQueue(q);
    score = 0;
    level = 1;
    lines = 0;
    hold = null;
    canHold = true;
    status = "running";
    current = null;
    spawn();
    if (status === "running") startTimer();
    render();
  }

  function parseRows(rows) {
    var b = emptyBoard();
    if (!Array.isArray(rows)) return b;
    for (var r = 0; r < ROWS && r < rows.length; r++) {
      var line = String(rows[r]);
      for (var c = 0; c < COLS && c < line.length; c++) {
        var ch = line.charAt(c).toUpperCase();
        b[r][c] = TYPES.indexOf(ch) !== -1 ? ch : null;
      }
    }
    return b;
  }

  function boardToRows() {
    return board.map(function (row) {
      return row.map(function (v) { return v || "."; }).join("");
    });
  }

  // ---- Keyboard ----
  var KEYS = {
    ArrowLeft: "left",
    ArrowRight: "right",
    ArrowUp: "rotateCW",
    x: "rotateCW",
    X: "rotateCW",
    ArrowDown: "softDrop",
    " ": "hardDrop",
    Spacebar: "hardDrop",
    c: "hold",
    C: "hold",
    Shift: "hold"
  };

  document.addEventListener("keydown", function (e) {
    if (status === "gameover" && e.key === "Enter") {
      e.preventDefault();
      newGame();
      return;
    }
    var action = KEYS[e.key];
    if (!action) return;
    e.preventDefault();
    ACTIONS[action]();
    render();
  });

  document.getElementById("restart").addEventListener("click", function () {
    newGame();
  });

  // ---- Test control surface ----
  window.__tetris = {
    newGame: function (q) { newGame(q); },
    setQueue: function (q) {
      queue = sanitizeQueue(q);
      fillQueue();
      render();
    },
    setBoard: function (rows) {
      board = parseRows(rows);
      render();
    },
    tick: function (n) {
      var count = n === undefined ? 1 : Math.max(0, Math.floor(Number(n)) || 0);
      for (var i = 0; i < count; i++) gravityStep();
      render();
    },
    input: function (action) {
      var fn = ACTIONS[action];
      if (!fn) return;
      fn();
      render();
    },
    setLevel: function (n) {
      var v = Math.floor(Number(n));
      if (!(v >= 1)) return;
      level = v;
      if (timer !== null) startTimer();
      render();
    },
    getBoard: function () { return boardToRows(); },
    getState: function () {
      return {
        current: current ? { type: current.type, cells: pieceCells(current, 0, 0) } : null,
        next: queue.slice(),
        score: score,
        level: level,
        lines: lines,
        dropInterval: gravityInterval(),
        hold: hold,
        status: status
      };
    }
  };

  newGame();
})();
</script>
</body>
